package dev.pocketrun.runtime

import java.io.File

enum class RuntimeKind(val id: String, val label: String) {
    PYTHON("python", "Python"),
    NODE("node", "Node"),
    NPX("npx", "npx"),
    ;

    companion object {
        fun from(id: String): RuntimeKind? = entries.firstOrNull { it.id == id }
    }
}

/**
 * A single execution. [target] is a script path for PYTHON/NODE and a package
 * specifier for NPX; [args] are the arguments after the script name.
 */
data class ExecRequest(
    val kind: RuntimeKind,
    val target: String,
    val args: List<String> = emptyList(),
    val cwd: File? = null,
    val stdin: String? = null,
)

data class ExecResult(
    val exitCode: Int,
    val stdout: String,
    val stderr: String,
    val durationMs: Long,
    val truncated: Boolean = false,
) {
    val isSuccess: Boolean get() = exitCode == 0
}

enum class OutputStream { STDOUT, STDERR }

/** Called from the runtime's worker thread; implementations must not block. */
interface OutputListener {
    fun onOutput(stream: OutputStream, text: String) {}
    fun onFinished(result: ExecResult) {}
    fun onFailed(error: Throwable) {}
}

interface ExecutionHandle {
    val isRunning: Boolean
    fun cancel()
}

/** One language runtime inside the app. */
interface ScriptRuntime {
    val kind: RuntimeKind
    val version: String
    fun isAvailable(): Boolean
    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.agent.LlmClient
import dev.pocketrun.core.Workspace
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * The opencode agent loop: user message in, tool calls out, tool results back
 * in, repeat until a plain-text answer (or the round budget). The system prompt
 * is assembled opencode-style: base agent prompt + AGENTS.md instructions +
 * current todos; skills are advertised through the `skill` tool description.
 *
 * Long turns are the normal case, not the exception, so the loop is built for
 * them: the answer is streamed (so the connection never goes idle and ⏹ works),
 * the history is trimmed before every request (so the prompt stays inside the
 * model's context), and a turn that runs out of rounds is saved instead of lost
 * — the user continues it with `/continue`.
 */
class OpenCodeAgent(
    private val workspace: Workspace,
    private val tools: OpenCodeTools,
    private val clientFactory: () -> LlmClient,
    private val projectDir: File?,
    private val maxSteps: Int = 12,
    private val askMode: Boolean = false,
    private val hasGitHub: Boolean = false,
    /** Polled before every request and between tool calls: this is what ⏹ does. */
    private val isCancelled: () -> Boolean = { false },
    private val maxHistoryChars: Int = HistoryTrimmer.DEFAULT_MAX_CHARS,
) {

    sealed class Event {
        /** A new model round has started (1-based, with the budget). */
        data class Round(val step: Int, val maxSteps: Int) : Event()
        /** The model is streaming an answer; [preview] is what it has written so far. */
        data class Thinking(val preview: String) : Event()
        data class AssistantText(val text: String) : Event()
        data class ToolStart(val name: String, val args: String) : Event()
        data class ToolDone(val name: String, val result: String) : Event()
        /** Something worth telling the user without failing the turn (a retry, a trim). */
        data class Note(val text: String) : Event()
        data class Failed(val message: String) : Event()
    }

    companion object {
        const val CANCELLED = "остановлено пользователем"

        /** Sent when the model answers with nothing at all. */
        const val CONTINUE_NUDGE =
            "Your previous answer was empty. Continue the task, then finish with a short summary of what you did."

        /** Sent by the `/continue` chat command. */
        const val CONTINUE_PROMPT = "Продолжай с того места, где остановился."
    }

    /**
     * Runs one user turn against [messages] (the session history WITHOUT the
     * system message) and returns the extended history.
     */
    fun run(userText: String, messages: JSONArray, onEvent: (Event) -> Unit): JSONArray {
        val full = JSONArray()
        full.put(systemMessage())
        for (i in 0 until messages.length()) full.put(messages.get(i))
        if (userText.isNotBlank()) {
            full.put(JSONObject().put("role", "user").put("content", userText))
        }

        var budget = maxSteps
        var trimmed = false
        try {
            while (budget > 0) {
                if (isCancelled()) {
                    onEvent(Event.Failed(CANCELLED))
                    break
                }
                budget--
                onEvent(Event.Round(maxSteps - budget, maxSteps))

                // Keep the prompt inside the model's context: old tool output is
                // excerpted and, if needed, old rounds are dropped.
                val request = HistoryTrimmer.trim(full, maxHistoryChars)
                if (request !== full && !trimmed) {
                    trimmed = true
                    onEvent(Event.Note("История хода сокращена, чтобы запрос уложился в контекст модели"))
                }

                val preview = StringBuilder()
                var lastEmit = 0L
                val response = try {
                    clientFactory().chat(request, tools.definitions(), isCancelled) { delta ->
                        preview.append(delta)
                        val now = System.currentTimeMillis()
                        if (now - lastEmit > 400) {
                            lastEmit = now
                            onEvent(Event.Thinking(preview.toString()))
                        }
                    }
                } finally {
                    onEvent(Event.Thinking(""))
                }

                if (response.toolCalls.isEmpty() && response.content.isNullOrBlank()) {
                    // Nothing usable came back. Nudge once instead of ending the
                    // turn in silence; the budget still counts this round.
                    full.put(JSONObject().put("role", "assistant").put("content", "(пустой ответ)"))
                    full.put(JSONObject().put("role", "user").put("content", CONTINUE_NUDGE))
                    continue
                }

                if (response.toolCalls.isEmpty()) {
                    val text = response.content.orEmpty()
                    full.put(JSONObject().put("role", "assistant").put("content", text))
                    if (text.isNotBlank()) onEvent(Event.AssistantText(text))
                    return finish(full)
                }

                val assistantMsg = JSONObject().put("role", "assistant")
                if (response.content != null) {
                    assistantMsg.put("content", response.content)
                    if (response.content.isNotBlank()) onEvent(Event.AssistantText(response.content))
                }
                val calls = JSONArray()
                response.toolCalls.forEach { call ->
                    calls.put(
                        JSONObject().apply {
                            put("id", call.id)
                            put("type", "function")
                            put("function", JSONObject().put("name", call.name).put("arguments", call.arguments))
                        },
                    )
                }
                assistantMsg.put("tool_calls", calls)
                full.put(assistantMsg)

                var interrupted = false
                for (call in response.toolCalls) {
                    if (isCancelled()) {
                        interrupted = true
                        break
                    }
                    onEvent(Event.ToolStart(call.name, prettyArgs(call.arguments)))
                    val result = tools.execute(call.name, call.arguments)
                    onEvent(Event.ToolDone(call.name, result))
                    full.put(
                        JSONObject().apply {
                            put("role", "tool")
                            put("tool_call_id", call.id)
                            put("content", result)
                        },
                    )
                }
                if (interrupted) {
                    // The calls that never ran are answered by finish(), which
                    // repairs the tail of the history before it is saved.
                    onEvent(Event.Failed(CANCELLED))
                    break
                }
            }
            if (!isCancelled() && budget <= 0) {
                onEvent(
                    Event.Failed(
                        "достигнут лимит раундов ($maxSteps) — файлы и история сохранены, " +
                            "напишите /continue, и агент продолжит с этого места",
                    ),
                )
            }
        } catch (t: Throwable) {
            onEvent(Event.Failed(t.message ?: t.javaClass.simpleName))
        }
        return finish(full)
    }

    /**
     * Ends the turn: answers any tool call that never got a result (a stopped
     * or failed round) and drops the system message. A history with an
     * unanswered tool call is rejected by strict providers, and this history is
     * what the next request and the next session are built from.
     */
    private fun finish(messages: JSONArray): JSONArray {
        val answered = mutableSetOf<String>()
        for (i in 0 until messages.length()) {
            val m = messages.optJSONObject(i) ?: continue
            if (m.optString("role") == "tool") answered += m.optString("tool_call_id")
        }
        for (i in messages.length() - 1 downTo 0) {
            val m = messages.optJSONObject(i) ?: continue
            if (m.optString("role") != "assistant") continue
            val calls = m.optJSONArray("tool_calls") ?: return stripSystem(messages)
            for (c in 0 until calls.length()) {
                val id = calls.getJSONObject(c).optString("id")
                if (id.isEmpty() || id in answered) continue
                messages.put(
                    JSONObject()
                        .put("role", "tool")
                        .put("tool_call_id", id)
                        .put("content", "(выполнение прервано — ход остановлен)"),
                )
            }
            break
        }
        return stripSystem(messages)
    }

    // ---------------------------------------------------------------- prompt

    private fun systemMessage(): JSONObject {
        // instructions (AGENTS.md etc.) for the current project
        val instr = Instructions(workspace).collect(projectDir)
        val todosBlock = if (tools.todos.isEmpty()) {
            "No todos yet."
        } else {
            tools.todos.joinToString("\n") { "  - [${it.status}] ${it.content}" }
        }

        val prompt = buildString {
            appendLine("You are opencode, an AI coding agent running inside the PocketRun app on Android. You help with code and files in the user's sandbox.")
            appendLine()
            appendLine("# Environment")
            appendLine("- Project directory: ${projectDir?.relativeToOrNull(workspace.root)?.path ?: "."} (relative paths in tools resolve there)")
            appendLine("- Sandbox root: the workspace; nothing outside it is accessible.")
            appendLine("- The `bash` tool is a restricted mini-shell: ${MiniShell.COMMANDS.joinToString(", ")}.")
            appendLine("  - `python` runs CPython 3.13 (standard library only, no pip);")
            appendLine("  - `node` runs a Node.js-compatible layer (require/fs/timers/Buffer/http work; no class/async-await/import syntax);")
            appendLine("  - `npx <pkg> [args]` installs and runs pure-JS npm packages (no native addons; prefer older releases of big packages, e.g. cowsay@1.4.0);")
            appendLine("  - `npm init -y`, `npm install <pkg>`, `npm run <script>`, `npm ls` manage a real node project: package.json is created in the project, installed packages are visible to require(), scripts run through the shell. Pure-JS packages only (no native addons).")
            appendLine("  - commands may run up to ${OpenCodeTools.BASH_TIMEOUT_MS / 60_000} minutes each; `sleep` up to ${MiniShell.MAX_SLEEP_SECONDS} seconds.")
            appendLine("- `webfetch` can read documentation pages.")
            appendLine()
            appendLine("# How to work")
            appendLine("- Explore first (list, read, glob, grep), then act (edit, write, apply_patch, bash), then verify by running code.")
            appendLine("- Prefer precise edits over rewriting whole files.")
            appendLine("- Use todowrite for multi-step tasks; keep the list current.")
            appendLine("- Ask the user with the question tool when requirements are ambiguous.")
            appendLine("- If a tool fails, read the error and adjust; do not repeat the same failing call more than twice.")
            appendLine("- Keep going until the task is actually done: you have up to $maxSteps model rounds for this request, and long builds and downloads are normal — plan for them instead of stopping early.")
            appendLine("- When you must wait for something (a CI run, a build), block on a single waiting call (github run_wait) instead of polling in a loop: polling wastes rounds.")
            appendLine("- For workflows the user repeats, suggest saving a skill: a folder .opencode/skills/<name>/SKILL.md with `name` and `description` in YAML frontmatter — you can create it with apply_patch yourself, then load it with the skill tool.")
            appendLine("- Answer in the user's language (usually Russian). Be concise; show what you did.")
            if (askMode) {
                appendLine()
                appendLine("# Clarification mode (user preference)")
                appendLine("Before any non-trivial task, ask the user 1-3 short clarifying questions with the question tool (each with concrete answer options). Only proceed automatically when the request is completely unambiguous or you already asked in this session.")
            }
            if (hasGitHub) {
                appendLine()
                appendLine("# GitHub and Actions runners")
                appendLine("The `github` tool talks to the GitHub REST API with the user's token. GitHub Actions runners are full Linux machines (ubuntu-latest): use them for anything the mobile sandbox cannot run — npm packages, opencode itself, compilers, heavy tests.")
                appendLine("Runner pattern:")
                appendLine("1. repo_create (private by default) → 2. push code + .github/workflows/run.yml (one commit, atomically) → 3. dispatch → 4. github run_wait {repo, timeout_sec} — blocks until the run finishes and returns the conclusion, the jobs and the log tail → 5. artifacts/artifact_download.")
                appendLine("Never poll `runs` in a loop: run_wait is one round instead of ten, and it works for anything that takes minutes.")
                appendLine("Example workflow the user can adapt:")
                appendLine("```yaml")
                appendLine("name: agent-runner")
                appendLine("on: workflow_dispatch")
                appendLine("jobs:")
                appendLine("  run:")
                appendLine("    runs-on: ubuntu-latest")
                appendLine("    steps:")
                appendLine("      - uses: actions/checkout@v4")
                appendLine("      - uses: actions/setup-node@v4")
                appendLine("        with: { node-version: 22 }")
                appendLine("      - run: npm install")
                appendLine("      # opencode inside the runner:")
                appendLine("      - run: npm i -g opencode-ai && opencode run --model opencode/claude-sonnet-4-5 \"<task>\"")
                appendLine("        env: { OPENCODE_API_KEY: '${'$'}{{ secrets.ZEN_KEY }}' }")
                appendLine("      - uses: actions/upload-artifact@v4")
                appendLine("        with: { name: out, path: out/ }")
                appendLine("```")
                appendLine("Never print or commit the user's tokens; reference secrets like \${{ secrets.NAME }} instead.")
            }
            appendLine()
            appendLine("# Current todos")
            appendLine(todosBlock)
            if (instr.text.isNotEmpty()) {
                appendLine()
                appendLine("# Instructions")
                appendLine(instr.text)
            }
        }
        return JSONObject().put("role", "system").put("content", prompt.trim())
    }

    private fun stripSystem(messages: JSONArray): JSONArray {
        val out = JSONArray()
        for (i in 0 until messages.length()) {
            val m = messages.get(i)
            if (m is JSONObject && m.optString("role") == "system") continue
            out.put(m)
        }
        return out
    }

    private fun prettyArgs(argsJson: String): String = try {
        val obj = JSONObject(argsJson)
        if (obj.length() == 0) "" else obj.toString().take(200)
    } catch (t: Throwable) {
        argsJson.take(200)
    }
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.RuntimeKind
import dev.pocketrun.runtime.js.JsRuntime
import dev.pocketrun.runtime.npm.NpxRuntime
import dev.pocketrun.runtime.python.PythonRuntime
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * The `bash` tool of the opencode agent: a small POSIX-flavoured shell that
 * runs entirely inside the workspace sandbox. Supports quoting, `&&` chaining,
 * `|` pipes and `>` / `>>` redirection for the built-in commands, plus
 * `python`, `node` and `npx` routed to the real app runtimes.
 *
 * Anything it cannot do fails with a clear message instead of pretending —
 * the model is told up front (in the system prompt) which commands exist.
 */
class MiniShell(
    private val workspace: Workspace,
    private val jsRuntime: JsRuntime,
    private val npxRuntime: NpxRuntime,
) {

    companion object {
        const val MAX_OUTPUT = 32 * 1024
        const val MAX_FILE = 2 * 1024 * 1024

        /** `sleep` in the sandbox: long enough to wait for a job, short enough not to hang a turn. */
        const val MAX_SLEEP_SECONDS = 120f
        val COMMANDS = listOf(
            "cat", "cd", "cp", "date", "echo", "env", "false", "find", "grep", "head",
            "ls", "mkdir", "mv", "node", "npm", "npx", "pwd", "python", "rm", "sleep", "tail",
            "touch", "true", "uname", "wc", "which", "help",
        )
        private val HELP = """
            Доступные команды: ${COMMANDS.joinToString(" ")}
            python <file.py> | python -c '<код>'   — CPython 3.13 (стандартная библиотека)
            node <file.js>  | node -e '<код>'      — Node-совместимый слой (без class/async/import)
            npx <пакет> [аргументы]               — чистые JS npm-пакеты
            npm init -y | npm install <пакет> | npm run <скрипт> | npm ls
                                                   — управление node-проектом (install качает
                                                     чистые JS-пакеты; require() их видит)
            sleep <секунды>                       — пауза (максимум ${MAX_SLEEP_SECONDS.toInt()} с)
            Поддерживаются кавычки, && , | и > >> для встроенных команд.
        """.trimIndent()
    }

    data class Result(val exitCode: Int, val output: String) {
        val ok: Boolean get() = exitCode == 0
    }

    /** Executes [commandLine] with [cwd] as the working directory. */
    fun execute(commandLine: String, cwd: File, timeoutMs: Long = OpenCodeTools.BASH_TIMEOUT_MS): Result {
        var dir = if (cwd.isDirectory) cwd else workspace.root
        val segments = splitAnd(commandLine)
        if (segments.isEmpty()) return Result(0, "")
        val out = StringBuilder()
        var lastExit = 0
        for (segment in segments) {
            if (lastExit != 0) break
            val r = runPipeline(segment, dir, timeoutMs) { d -> dir = d }
            out.append(r.output)
            lastExit = r.exitCode
        }
        return Result(lastExit, cap(out.toString()))
    }

    // ---------------------------------------------------------------- structure

    /** Splits on && at top level (outside quotes). */
    private fun splitAnd(line: String): List<String> {
        val parts = mutableListOf<String>()
        val cur = StringBuilder()
        var quote: Char? = null
        var i = 0
        while (i < line.length) {
            val c = line[i]
            when {
                quote != null -> {
                    cur.append(c)
                    if (c == quote) quote = null
                }
                c == '"' || c == '\'' -> { quote = c; cur.append(c) }
                c == '&' && i + 1 < line.length && line[i + 1] == '&' -> {
                    if (cur.isNotBlank()) parts += cur.toString().trim()
                    cur.clear()
                    i++
                }
                else -> cur.append(c)
            }
            i++
        }
        if (cur.isNotBlank()) parts += cur.toString().trim()
        return parts
    }

    /** Runs one `cmd | cmd | cmd [> file]` pipeline segment. */
    private fun runPipeline(
        segment: String,
        dir: File,
        timeoutMs: Long,
        onCd: (File) -> Unit,
    ): Result {
        // split on top-level |
        val stages = mutableListOf<String>()
        val cur = StringBuilder()
        var quote: Char? = null
        var i = 0
        while (i < segment.length) {
            val c = segment[i]
            when {
                quote != null -> { cur.append(c); if (c == quote) quote = null }
                c == '"' || c == '\'' -> { quote = c; cur.append(c) }
                c == '|' -> { stages += cur.toString().trim(); cur.clear() }
                else -> cur.append(c)
            }
            i++
        }
        if (cur.isNotBlank()) stages += cur.toString().trim()
        if (stages.isEmpty()) return Result(0, "")

        var input = ""
        var exit = 0
        var redirectFile: File? = null
        var append = false

        for ((index, stage) in stages.withIndex()) {
            val (tokens, redir, redirAppend) = extractRedirect(tokenize(stage), dir)
            redirectFile = redir
            append = redirAppend
            if (tokens.isEmpty()) continue
            val cmd = tokens[0]
            val args = tokens.drop(1)

            // runtime commands ignore stdin/pipes — they run to completion
            val r = when (cmd) {
                "python", "python3" -> runPython(args, dir, timeoutMs)
                "node" -> runNode(args, dir, timeoutMs)
                "npx" -> runNpx(args, dir, timeoutMs)
                "npm" -> npm(args, dir, timeoutMs)
                else -> runBuiltin(cmd, args, dir, input, onCd)
            }
            exit = r.exitCode
            input = r.output
            // redirect only applies to the last stage
            if (index == stages.lastIndex) {
                if (redirectFile != null) {
                    writeToFile(redirectFile, input, append)
                    return Result(r.exitCode, "")
                }
            }
        }
        return Result(exit, input)
    }

    /** `> file` / `>> file` on built-in commands. */
    private fun extractRedirect(tokens: List<String>, dir: File): Triple<List<String>, File?, Boolean> {
        val gt = tokens.indexOfFirst { it == ">" || it == ">>" }
        if (gt < 0 || gt + 1 >= tokens.size) return Triple(tokens, null, false)
        val file = sandboxPath(tokens[gt + 1], dir)
        return Triple(tokens.subList(0, gt), file, tokens[gt] == ">>")
    }

    // ---------------------------------------------------------------- builtins

    private fun runBuiltin(cmd: String, args: List<String>, dir: File, stdin: String, onCd: (File) -> Unit): Result {
        return when (cmd) {
            "pwd" -> Result(0, dir.relativeToOrNull(workspace.root)?.let { "./$it" } ?: dir.absolutePath + "\n")
            "cd" -> {
                val target = sandboxPath(args.firstOrNull() ?: ".", dir)
                if (target == null || !target.isDirectory) Result(1, "cd: ${args.firstOrNull() ?: ""}: нет такого каталога\n")
                else { onCd(target); Result(0, "") }
            }
            "ls" -> ls(args, dir)
            "cat" -> cat(args, dir, stdin)
            "echo" -> Result(0, args.joinToString(" ") + "\n")
            "mkdir" -> mkdir(args, dir)
            "rm" -> rm(args, dir)
            "mv" -> mv(args, dir)
            "cp" -> cp(args, dir)
            "touch" -> {
                var ok = 0
                for (a in flagsFree(args)) {
                    val f = sandboxPath(a, dir)
                    if (f == null) { ok = 1; continue }
                    if (f.exists()) f.setLastModified(System.currentTimeMillis()) else f.createNewFile()
                }
                Result(ok, "")
            }
            "head" -> headTail(args, dir, fromStart = true)
            "tail" -> headTail(args, dir, fromStart = false)
            "wc" -> wc(args, dir, stdin)
            "find" -> find(args, dir)
            "grep" -> shellGrep(args, dir, stdin)
            "env" -> Result(0, "HOME=${workspace.root.absolutePath}\nLANG=C.UTF-8\n")
            "date" -> Result(0, SimpleDateFormat("EEE MMM dd HH:mm:ss yyyy", Locale.US).format(Date()) + "\n")
            "sleep" -> {
                val sec = args.firstOrNull()?.toFloatOrNull() ?: return Result(1, "sleep: нужен аргумент в секундах\n")
                if (sec > MAX_SLEEP_SECONDS) return Result(1, "sleep: максимум ${MAX_SLEEP_SECONDS.toInt()} секунд\n")
                if (sec > 0) Thread.sleep((sec * 1000).toLong())
                Result(0, "")
            }
            "uname" -> Result(0, "Linux aarch64 PocketRun\n")
            "which" -> Result(if (args.firstOrNull() in COMMANDS) 0 else 1, if (args.firstOrNull() in COMMANDS) "/bin/${args.first()}\n" else "")
            "true" -> Result(0, "")
            "false" -> Result(1, "")
            "help" -> Result(0, HELP + "\n")
            else -> Result(127, "bash: $cmd: команда не найдена (доступно: ${COMMANDS.joinToString(", ")})\n")
        }
    }

    private fun flagsFree(args: List<String>): List<String> = args.filter { !it.startsWith("-") }

    private fun ls(args: List<String>, dir: File): Result {
        val all = args.any { it == "-a" || it == "-la" || it == "-al" }
        val long = args.any { it == "-l" || it == "-la" || it == "-al" || it == "-lh" }
        val targets = flagsFree(args).ifEmpty { listOf(".") }
        val out = StringBuilder()
        var exit = 0
        for (t in targets) {
            val f = sandboxPath(t, dir)
            if (f == null || !f.exists()) { exit = 1; out.append("ls: $t: нет такого файла\n"); continue }
            val entries = when {
                f.isDirectory -> f.listFiles()?.sortedBy { it.name.lowercase() } ?: emptyList()
                else -> listOf(f)
            }.filter { all || !it.name.startsWith(".") }
            if (targets.size > 1) out.append("${t}:\n")
            for (e in entries) {
                if (long) {
                    out.append("%s %8d  %s\n".format(if (e.isDirectory()) "d" else "-", e.length(), e.name))
                } else {
                    out.append(if (e.isDirectory()) e.name + "/" else e.name)
                    out.append("\n")
                }
            }
            if (targets.size > 1) out.append("\n")
        }
        return Result(exit, out.toString())
    }

    private fun cat(args: List<String>, dir: File, stdin: String): Result {
        if (args.isEmpty() || args.first() == "-") return Result(0, stdin)
        val out = StringBuilder()
        var exit = 0
        for (a in args) {
            val f = sandboxPath(a, dir)
            if (f == null || !f.isFile) { exit = 1; out.append("cat: $a: нет такого файла\n"); continue }
            if (f.length() > MAX_FILE) { exit = 1; out.append("cat: $a: файл слишком большой\n"); continue }
            out.append(f.readText(Charsets.UTF_8))
        }
        return Result(exit, out.toString())
    }

    private fun mkdir(args: List<String>, dir: File): Result {
        val recursive = args.any { it == "-p" }
        var exit = 0
        val out = StringBuilder()
        for (a in flagsFree(args)) {
            val f = sandboxPath(a, dir)
            if (f == null) { exit = 1; continue }
            if (f.exists()) {
                if (!recursive) { exit = 1; out.append("mkdir: $a: уже существует\n") }
                continue
            }
            if (recursive) f.mkdirs() else f.mkdir()
            if (!f.isDirectory) { exit = 1; out.append("mkdir: $a: не удалось создать\n") }
        }
        return Result(exit, out.toString())
    }

    private fun rm(args: List<String>, dir: File): Result {
        val recursive = args.any { it == "-r" || it == "-rf" || it == "-fr" || it == "-R" }
        var exit = 0
        val out = StringBuilder()
        for (a in flagsFree(args)) {
            val f = sandboxPath(a, dir)
            if (f == null || !f.exists()) { exit = 1; out.append("rm: $a: нет такого файла\n"); continue }
            if (f.isDirectory && !recursive) { exit = 1; out.append("rm: $a: это каталог (нужен -r)\n"); continue }
            if (!f.deleteRecursively()) { exit = 1; out.append("rm: $a: не удалось удалить\n") }
        }
        return Result(exit, out.toString())
    }

    private fun mv(args: List<String>, dir: File): Result {
        val files = flagsFree(args)
        if (files.size < 2) return Result(1, "mv: использование: mv <откуда> <куда>\n")
        val from = sandboxPath(files[0], dir) ?: return Result(1, "mv: путь вне песочницы\n")
        val to = sandboxPath(files[1], dir) ?: return Result(1, "mv: путь вне песочницы\n")
        if (!from.exists()) return Result(1, "mv: ${files[0]}: нет такого файла\n")
        val target = if (to.isDirectory) File(to, from.name) else to
        target.parentFile?.mkdirs()
        return if (from.renameTo(target)) Result(0, "") else Result(1, "mv: не удалось переместить\n")
    }

    private fun cp(args: List<String>, dir: File): Result {
        val files = flagsFree(args)
        if (files.size < 2) return Result(1, "cp: использование: cp <откуда> <куда>\n")
        val from = sandboxPath(files[0], dir) ?: return Result(1, "cp: путь вне песочницы\n")
        val to = sandboxPath(files[1], dir) ?: return Result(1, "cp: путь вне песочницы\n")
        if (!from.exists()) return Result(1, "cp: ${files[0]}: нет такого файла\n")
        val target = if (to.isDirectory) File(to, from.name) else to
        return try {
            if (from.isDirectory) from.copyRecursively(target, overwrite = true)
            else { target.parentFile?.mkdirs(); from.copyTo(target, overwrite = true) }
            Result(0, "")
        } catch (t: Throwable) { Result(1, "cp: ${t.message}\n") }
    }

    private fun headTail(args: List<String>, dir: File, fromStart: Boolean): Result {
        // head [-n N] [-N] file — `head -n 5 f`, `head -5 f`, `head f` all work.
        var n = 10
        val files = mutableListOf<String>()
        var i = 0
        while (i < args.size) {
            when {
                args[i] == "-n" && i + 1 < args.size && args[i + 1].toIntOrNull() != null ->
                    n = args[++i].toInt()
                args[i].startsWith("-") && args[i].removePrefix("-").toIntOrNull() != null ->
                    n = args[i].removePrefix("-").toInt()
                !args[i].startsWith("-") -> files += args[i]
            }
            i++
        }
        if (files.isEmpty()) return Result(1, "${if (fromStart) "head" else "tail"}: нужен файл\n")
        val f = sandboxPath(files[0], dir) ?: return Result(1, "путь вне песочницы\n")
        if (!f.isFile) return Result(1, "${files[0]}: нет такого файла\n")
        val lines = f.readText(Charsets.UTF_8).lines()
        val picked = if (fromStart) lines.take(n) else lines.takeLast(n)
        return Result(0, picked.joinToString("\n") + "\n")
    }

    private fun wc(args: List<String>, dir: File, stdin: String): Result {
        val files = flagsFree(args)
        val text = when {
            files.isEmpty() -> stdin
            else -> sandboxPath(files.last(), dir)?.takeIf { it.isFile }?.readText(Charsets.UTF_8)
                ?: return Result(1, "wc: ${files.last()}: нет такого файла\n")
        }
        // A trailing newline does not start a new line (like wc -l).
        val lines = text.lines().let { if (text.endsWith("\n")) it.dropLast(1) else it }
        return Result(0, "%7d %7d %7d\n".format(lines.size, text.split(Regex("\\s+")).count { it.isNotEmpty() }, text.length))
    }

    private fun find(args: List<String>, dir: File): Result {
        // find [path] [-name pattern] [-type f|d]
        var start = dir
        var namePattern: String? = null
        var type: Char? = null
        var i = 0
        while (i < args.size) {
            when (args[i]) {
                "-name" -> { if (i + 1 < args.size) namePattern = args[++i] }
                "-type" -> { if (i + 1 < args.size) type = args[++i].firstOrNull() }
                else -> if (!args[i].startsWith("-")) start = sandboxPath(args[i], dir) ?: start
            }
            i++
        }
        val out = StringBuilder()
        start.walkTopDown().forEach { f ->
            if (out.length > MAX_OUTPUT) return@forEach
            if (type == 'f' && !f.isFile) return@forEach
            if (type == 'd' && !f.isDirectory) return@forEach
            val rel = f.relativeToOrNull(start) ?: return@forEach
            val path = if (rel.path == ".") start.name else start.name + "/" + rel.path
            if (namePattern == null || globMatch(namePattern, rel.path) || globMatch(namePattern, f.name)) {
                out.append(path).append('\n')
            }
        }
        return Result(0, out.toString())
    }

    private fun shellGrep(args: List<String>, dir: File, stdin: String): Result {
        val ignoreCase = args.any { it == "-i" }
        val rest = args.filter { it != "-i" && it != "-n" && !it.startsWith("-") }
        if (rest.isEmpty()) return Result(1, "grep: использование: grep [-i] <шаблон> [файл]\n")
        val pattern = try {
            if (ignoreCase) Regex(rest[0], RegexOption.IGNORE_CASE) else Regex(rest[0])
        } catch (t: Throwable) {
            return Result(2, "grep: плохой regex: ${t.message}\n")
        }
        val text = if (rest.size > 1) {
            sandboxPath(rest[1], dir)?.takeIf { it.isFile }?.readText(Charsets.UTF_8)
                ?: return Result(1, "grep: ${rest[1]}: нет такого файла\n")
        } else stdin
        val out = StringBuilder()
        text.lines().forEachIndexed { idx, line ->
            if (pattern.containsMatchIn(line)) out.append("%d:%s\n".format(idx + 1, line))
        }
        return Result(if (out.isEmpty()) 1 else 0, out.toString())
    }

    // ---------------------------------------------------------------- runtimes

    private fun runPython(args: List<String>, dir: File, timeoutMs: Long): Result {
        if (!PythonRuntime.isAvailable()) {
            return Result(1, "python: рантайм ещё запускается, попробуйте снова через пару секунд\n")
        }
        return when {
            args.firstOrNull() == "-c" && args.size >= 2 -> runCodeFile("py", args[1], dir, timeoutMs, python = true)
            args.isEmpty() -> Result(1, "python: нужен файл или -c '<код>'\n")
            else -> {
                val f = sandboxPath(args[0], dir)
                    ?: return Result(1, "python: путь вне песочницы\n")
                if (!f.isFile) return Result(1, "python: ${args[0]}: нет такого файла\n")
                val r = PythonRuntime.executeSync(
                    ExecRequest(RuntimeKind.PYTHON, f.absolutePath, args.drop(1), dir),
                    timeoutMs,
                )
                Result(r.exitCode, r.stdout + (if (r.stderr.isNotBlank()) r.stderr else ""))
            }
        }
    }

    private fun runNode(args: List<String>, dir: File, timeoutMs: Long): Result {
        return when {
            args.firstOrNull() == "-e" && args.size >= 2 -> runCodeFile("js", args[1], dir, timeoutMs, python = false)
            args.isEmpty() -> Result(1, "node: нужен файл или -e '<код>'\n")
            else -> {
                val f = sandboxPath(args[0], dir)
                    ?: return Result(1, "node: путь вне песочницы\n")
                if (!f.isFile) return Result(1, "node: ${args[0]}: нет такого файла\n")
                val r = jsRuntime.executeSync(
                    ExecRequest(RuntimeKind.NODE, f.absolutePath, args.drop(1), dir),
                    timeoutMs,
                )
                Result(r.exitCode, r.stdout + (if (r.stderr.isNotBlank()) r.stderr else ""))
            }
        }
    }

    private fun runNpx(args: List<String>, dir: File, timeoutMs: Long): Result {
        val spec = args.firstOrNull() ?: return Result(1, "npx: укажите пакет\n")
        val r = npxRuntime.executeSync(
            ExecRequest(RuntimeKind.NPX, spec, args.drop(1), dir),
            timeoutMs,
        )
        return Result(r.exitCode, r.stdout + (if (r.stderr.isNotBlank()) r.stderr else ""))
    }

    // ---------------------------------------------------------------- npm

    /**
     * A minimal `npm` for the sandbox: init creates package.json, install
     * downloads pure-JS packages (into the shared store, which require()
     * already resolves), run executes package.json scripts through this shell.
     */
    private fun npm(args: List<String>, dir: File, timeoutMs: Long): Result {
        val sub = args.firstOrNull() ?: return Result(1, "npm: нужна подкоманда: init, install, run, test, ls\n")
        val rest = args.drop(1)
        return try {
            when (sub) {
                "init" -> npmInit(rest, dir)
                "install", "i", "add" -> npmInstall(rest, dir)
                "run" -> npmRun(rest, dir, timeoutMs)
                "test" -> npmRun(listOf("test"), dir, timeoutMs)
                "ls", "list" -> npmLs(dir)
                "--version", "-v" -> Result(0, "npm (PocketRun) — init / install / run / test / ls\n")
                else -> Result(1, "npm: неизвестная подкоманда '$sub' (есть: init, install, run, test, ls)\n")
            }
        } catch (t: Throwable) {
            Result(1, "npm: ${t.message ?: t.javaClass.simpleName}\n")
        }
    }

    private fun npmInit(args: List<String>, dir: File): Result {
        val pkg = File(dir, "package.json")
        if (pkg.isFile && args.none { it == "-y" || it == "--yes" || it == "-f" || it == "--force" }) {
            return Result(1, "npm: package.json уже существует (npm init -y чтобы перезаписать)\n")
        }
        val json = org.json.JSONObject()
            .put("name", dir.name.replace(Regex("[^a-z0-9-]"), "-").trim('-').ifEmpty { "project" })
            .put("version", "1.0.0")
            .put("description", "")
            .put("main", "index.js")
            .put(
                "scripts",
                org.json.JSONObject().put("test", "echo \"Error: no test specified\" && exit 1"),
            )
        pkg.writeText(json.toString(2) + "\n", Charsets.UTF_8)
        return Result(0, "создан package.json (${json.optString("name")})\n")
    }

    private fun npmInstall(args: List<String>, dir: File): Result {
        val pkg = File(dir, "package.json")
        val manifest = if (pkg.isFile) org.json.JSONObject(pkg.readText(Charsets.UTF_8)) else org.json.JSONObject()
        val specs = args.filter { !it.startsWith("-") }
        val toInstall: List<Pair<String, String?>> = if (specs.isEmpty()) {
            // no arguments: install everything from package.json dependencies
            val deps = manifest.optJSONObject("dependencies")
                ?: return Result(1, "npm: нет пакетов для установки и нет dependencies в package.json\n")
            deps.keys().asSequence().map { it to deps.optString(it).takeIf { r -> r != "*" } }.toList()
        } else {
            specs.mapNotNull { raw ->
                NpxRuntime.parseSpec(raw)?.let { it.name to it.version }
            }.ifEmpty { return Result(1, "npm: не удалось разобрать имена пакетов\n") }
        }
        val out = StringBuilder()
        for ((name, version) in toInstall) {
            val installed = npxRuntime.install(
                NpxRuntime.PackageSpec(name, version),
                log = { line -> out.append(line).append('\n') },
            )
            val actual = org.json.JSONObject(File(installed, "package.json").readText(Charsets.UTF_8)).optString("version")
            val deps = manifest.optJSONObject("dependencies") ?: org.json.JSONObject().also { manifest.put("dependencies", it) }
            deps.put(name, actual)
            out.append("✓ ").append(name).append('@').append(actual).append('\n')
        }
        if (pkg.isFile || toInstall.isNotEmpty()) {
            manifest.put("dependencies", manifest.optJSONObject("dependencies") ?: org.json.JSONObject())
            pkg.writeText(manifest.toString(2) + "\n", Charsets.UTF_8)
        }
        return Result(0, cap(out.toString()))
    }

    private fun npmRun(args: List<String>, dir: File, timeoutMs: Long): Result {
        val pkg = File(dir, "package.json")
        if (!pkg.isFile) return Result(1, "npm run: нет package.json в текущем каталоге\n")
        val manifest = org.json.JSONObject(pkg.readText(Charsets.UTF_8))
        val scripts = manifest.optJSONObject("scripts")
            ?: return Result(1, "npm run: в package.json нет секции scripts\n")
        val script = args.firstOrNull()
            ?: return Result(0, "доступные скрипты:\n" + scripts.keys().asSequence().joinToString("\n") { "  $it" } + "\n")
        val cmd = scripts.optString(script).takeIf { it.isNotEmpty() }
            ?: return Result(1, "npm run: нет скрипта \"$script\" (есть: ${scripts.keys().asSequence().joinToString(", ")})\n")
        val r = execute(cmd, dir, timeoutMs)
        return Result(r.exitCode, r.output)
    }

    private fun npmLs(dir: File): Result {
        val out = StringBuilder()
        val local = File(dir, "node_modules").takeIf { it.isDirectory }
        if (local != null) {
            out.append("локальные (node_modules):\n")
            local.listFiles()?.sortedBy { it.name }?.forEach { out.append("  ${it.name}\n") }
        }
        out.append("установленные пакеты (общий стор, виден из require):\n")
        npxRuntime.installedPackages().forEach { (n, v) -> out.append("  $n@$v\n") }
        return Result(0, out.toString().ifEmpty { "(ничего не установлено)\n" })
    }

    private fun runCodeFile(ext: String, code: String, dir: File, timeoutMs: Long, python: Boolean): Result {
        val scratch = File(workspace.cache, "opencode-shell").apply { mkdirs() }
        val f = File(scratch, "cmd.${if (python) "py" else "js"}")
        f.writeText(code, Charsets.UTF_8)
        val r = if (python) {
            if (!PythonRuntime.isAvailable()) return Result(1, "python: рантайм ещё запускается\n")
            PythonRuntime.executeSync(ExecRequest(RuntimeKind.PYTHON, f.absolutePath, emptyList(), dir), timeoutMs)
        } else {
            jsRuntime.executeSync(ExecRequest(RuntimeKind.NODE, f.absolutePath, emptyList(), dir), timeoutMs)
        }
        return Result(r.exitCode, r.stdout + (if (r.stderr.isNotBlank()) r.stderr else ""))
    }

    // ---------------------------------------------------------------- helpers

    private fun writeToFile(f: File, content: String, append: Boolean) {
        try {
            f.parentFile?.mkdirs()
            if (append) f.appendText(content, Charsets.UTF_8) else f.writeText(content, Charsets.UTF_8)
        } catch (_: Exception) { }
    }

    private fun sandboxPath(p: String, dir: File): File? = workspace.resolve(p, dir)

    /** Shell tokenizer: single/double quotes keep groups together. */
    internal fun tokenize(line: String): List<String> {
        val out = mutableListOf<String>()
        val cur = StringBuilder()
        var quote: Char? = null
        var has = false
        var i = 0
        while (i < line.length) {
            val c = line[i]
            when {
                quote != null -> {
                    if (c == quote) quote = null else cur.append(c)
                }
                c == '"' || c == '\'' -> { quote = c; has = true }
                c.isWhitespace() -> {
                    if (cur.isNotEmpty() || has) { out += cur.toString(); cur.clear(); has = false }
                }
                else -> cur.append(c)
            }
            i++
        }
        if (cur.isNotEmpty() || has) out += cur.toString()
        return out
    }

    /** Glob match with `*`, `?` and `**` support. */
    internal fun globMatch(pattern: String, path: String): Boolean {
        val regex = buildString {
            append('^')
            var i = 0
            while (i < pattern.length) {
                when (val c = pattern[i]) {
                    '*' -> if (i + 1 < pattern.length && pattern[i + 1] == '*') { append(".*"); i++ } else append("[^/]*")
                    '?' -> append('.')
                    else -> if (c in "\\^$.|+()[]{}") { append('\\'); append(c) } else append(c)
                }
                i++
            }
            append('$')
        }
        return Regex(regex).matches(path)
    }

    private fun cap(text: String): String =
        if (text.length <= MAX_OUTPUT) text else text.take(MAX_OUTPUT) + "\n… (обрезано)"
}

package dev.pocketrun.agent.opencode

import org.json.JSONArray
import org.json.JSONObject
import java.io.InputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
import java.util.Locale

/**
 * The `github` tool backend: a compact GitHub REST client. It lets the agent
 * manage repositories and **GitHub Actions runners** entirely from the app:
 * create a repo, commit files (including workflow files under
 * `.github/workflows`) in a single atomic commit, dispatch a workflow, block
 * until the run finishes, read logs and download artifacts. Inside an
 * `ubuntu-latest` runner anything can run — npm packages, opencode itself,
 * real compilers — which is the "heavy work" escape hatch of the mobile
 * sandbox.
 */
class GitHubClient(private val token: String) {

    companion object {
        private const val API = "https://api.github.com"
        private const val MAX_OUTPUT = 16 * 1024
        private const val MAX_ZIP_TEXT = 24 * 1024
        const val WAIT_POLL_MS = 10_000L
        const val MAX_WAIT_SEC = 1_800

        /** github ops that only read — auto-approved in manual confirmation mode. */
        val READ_OPS = setOf("repo_list", "file_get", "runs", "run_wait", "logs", "artifacts", "me")
    }

    class GitHubException(message: String) : Exception(message)

    /** A REST answer: status plus body (JSON text or raw). */
    private class Answer(val status: Int, val text: String)

    /** One path in a commit: new content, or a deletion. */
    private data class Change(val path: String, val content: String?, val delete: Boolean = false)

    // ---------------------------------------------------------------- core

    private fun conn(method: String, path: String, body: String?, raw: Boolean, followRedirects: Boolean): HttpURLConnection =
        (URL("$API$path").openConnection() as HttpURLConnection).apply {
            requestMethod = method
            connectTimeout = 15_000
            readTimeout = 90_000
            instanceFollowRedirects = followRedirects
            setRequestProperty("Accept", if (raw) "application/vnd.github.raw" else "application/vnd.github+json")
            setRequestProperty("Authorization", "Bearer $token")
            setRequestProperty("User-Agent", "PocketRun-Agent/1.5")
            setRequestProperty("X-GitHub-Api-Version", "2022-11-28")
            if (body != null) {
                doOutput = true
                setRequestProperty("Content-Type", "application/json")
            }
        }

    private fun call(
        method: String,
        path: String,
        body: String? = null,
        raw: Boolean = false,
        followRedirects: Boolean = true,
    ): Answer {
        val c = conn(method, path, body, raw, followRedirects)
        try {
            if (body != null) c.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
            val status = c.responseCode
            val text = (if (status in 200..299) c.inputStream else c.errorStream)
                ?.bufferedReader(Charsets.UTF_8)?.use { it.readText() } ?: ""
            return Answer(status, text)
        } finally {
            c.disconnect()
        }
    }

    private fun stream(method: String, path: String): InputStream {
        val c = conn(method, path, null, raw = false, followRedirects = true).apply { readTimeout = 120_000 }
        val status = c.responseCode
        if (status !in 200..299) {
            val err = c.errorStream?.bufferedReader()?.use { it.readText() } ?: ""
            c.disconnect()
            throw GitHubException("HTTP $status: ${err.take(300)}")
        }
        return c.inputStream
    }

    private fun ok(answer: Answer, what: String): String {
        if (answer.status !in 200..299) {
            val hint = when (answer.status) {
                401 -> " (проверьте GitHub-токен: нужны права repo и workflow)"
                403 -> " (токен без нужных прав или лимит API)"
                404 -> " (нет такого репозитория/файла — он приватный и токен без доступа?)"
                409 -> " (ветка изменилась — повторите, новые коммиты не тронуты)"
                422 -> " (файл уже существует или невалидные данные)"
                else -> ""
            }
            throw GitHubException("$what: HTTP ${answer.status}$hint: ${answer.text.take(300)}")
        }
        return answer.text
    }

    private fun get(path: String, what: String, raw: Boolean = false): String =
        ok(call("GET", path, raw = raw), what)

    private fun pretty(text: String): String {
        val t = try {
            if (text.startsWith("[")) JSONArray(text).toString(2) else JSONObject(text).toString(2)
        } catch (t: Throwable) {
            text
        }
        return t.take(MAX_OUTPUT) + if (t.length > MAX_OUTPUT) "\n… (обрезано)" else ""
    }

    private fun branchName(repo: String, requested: String?): String {
        if (!requested.isNullOrBlank()) return requested
        val repoJson = JSONObject(get("/repos/$repo", "repo info"))
        return repoJson.optString("default_branch", "main").ifEmpty { "main" }
    }

    // ---------------------------------------------------------------- ops

    fun me(): String {
        val o = JSONObject(get("/user", "user"))
        return "login=${o.optString("login")} name=${o.optString("name")}"
    }

    fun repoList(): String {
        val arr = JSONArray(get("/user/repos?sort=updated&per_page=30", "repo_list"))
        val sb = StringBuilder()
        for (i in 0 until arr.length()) {
            val r = arr.getJSONObject(i)
            sb.append("${r.optString("full_name")}  ${if (r.optBoolean("private")) "[private]" else "[public]"}  → ${r.optString("html_url")}\n")
        }
        return sb.toString().ifEmpty { "(репозиториев нет)" }
    }

    fun repoCreate(name: String, private: Boolean, description: String?): String {
        val body = JSONObject().put("name", name).put("private", private)
        if (!description.isNullOrBlank()) body.put("description", description)
        val o = JSONObject(ok(call("POST", "/user/repos", body.toString()), "repo_create"))
        return "создан ${o.optString("full_name")} → ${o.optString("html_url")} (default branch: ${o.optString("default_branch", "main")})"
    }

    /**
     * Commits files in ONE commit through the git data API: blobs → tree →
     * commit → ref update. The contents API would make a separate commit per
     * file (a workflow and its sources would land as five commits and could
     * trigger five runs), and it needs a GET per file to find the sha.
     */
    fun pushFiles(repo: String, files: List<Pair<String, String>>, message: String, branch: String?): String {
        if (files.isEmpty()) return "(нечего коммитить)"
        return commit(repo, files.map { Change(it.first, it.second) }, message, branch)
    }

    /** Deletes paths in one commit. */
    fun deleteFiles(repo: String, paths: List<String>, message: String, branch: String?): String {
        if (paths.isEmpty()) return "(нечего удалять)"
        return commit(repo, paths.map { Change(it, null, delete = true) }, message, branch)
    }

    private fun commit(repo: String, changes: List<Change>, message: String, branch: String?): String {
        val ref = branchName(repo, branch)
        return try {
            gitCommit(repo, changes, message, ref)
        } catch (e: GitHubException) {
            // The git data API can be unavailable for some tokens/scopes; the
            // contents API is the slower but wider path.
            if (changes.any { it.delete }) {
                changes.forEach { contentsDelete(repo, it.path, message) }
                return "удалено в $ref: ${changes.joinToString(", ") { it.path }}"
            }
            contentsCommit(repo, changes, message, ref)
        }
    }

    private fun gitCommit(repo: String, changes: List<Change>, message: String, branch: String): String {
        // One retry covers the case where someone pushed to the branch between
        // our read of the ref and our update of it.
        repeat(2) { attempt ->
            val head = headCommit(repo, branch)
            val baseTree = JSONObject(get("/repos/$repo/git/commits/$head", "git commit"))
                .optJSONObject("tree")?.optString("sha").orEmpty()
            val tree = JSONArray()
            for (c in changes) {
                val entry = JSONObject().put("path", c.path).put("mode", "100644").put("type", "blob")
                if (c.delete) {
                    entry.put("sha", JSONObject.NULL)
                } else {
                    val blob = JSONObject()
                        .put("content", Base64.getEncoder().encodeToString((c.content ?: "").toByteArray(Charsets.UTF_8)))
                        .put("encoding", "base64")
                    val sha = JSONObject(ok(call("POST", "/repos/$repo/git/blobs", blob.toString()), "git blob"))
                        .optString("sha")
                    entry.put("sha", sha)
                }
                tree.put(entry)
            }
            val treeSha = JSONObject(
                ok(
                    call(
                        "POST", "/repos/$repo/git/trees",
                        JSONObject().put("base_tree", baseTree).put("tree", tree).toString(),
                    ),
                    "git tree",
                ),
            ).optString("sha")
            val commitSha = JSONObject(
                ok(
                    call(
                        "POST", "/repos/$repo/git/commits",
                        JSONObject()
                            .put("message", message.ifBlank { "update" })
                            .put("tree", treeSha)
                            .put("parents", JSONArray().put(head))
                            .toString(),
                    ),
                    "git commit create",
                ),
            ).optString("sha")
            val refPath = "/repos/$repo/git/refs/heads/$branch"
            val update = call("PATCH", refPath, JSONObject().put("sha", commitSha).put("force", false).toString())
            if (update.status in 200..299) {
                return "коммит ${commitSha.take(7)} → $branch (${changes.size} " +
                    "${plural(changes.size, "файл", "файла", "файлов")}): " +
                    changes.joinToString(", ") { it.path }.take(600)
            }
            if (update.status == 422 && attempt == 0) return@repeat
            ok(update, "обновление ветки $branch")
        }
        throw GitHubException("ветка $branch всё время меняется — повторите push")
    }

    private fun headCommit(repo: String, branch: String): String =
        JSONObject(get("/repos/$repo/git/ref/heads/$branch", "ветка $branch"))
            .optJSONObject("object")?.optString("sha").orEmpty()
            .ifEmpty { throw GitHubException("ветка $branch не найдена") }

    /** Fallback path: one contents-API commit per file. */
    private fun contentsCommit(repo: String, changes: List<Change>, message: String, branch: String): String {
        val sb = StringBuilder()
        for (c in changes) {
            val existing = call("GET", "/repos/$repo/contents/${c.path}?ref=$branch")
            val sha = if (existing.status == 200) JSONObject(existing.text).optString("sha").takeIf { it.isNotEmpty() } else null
            val body = JSONObject()
                .put("message", message.ifBlank { "update" })
                .put("content", Base64.getEncoder().encodeToString((c.content ?: "").toByteArray(Charsets.UTF_8)))
                .put("branch", branch)
            if (sha != null) body.put("sha", sha)
            val answer = ok(call("PUT", "/repos/$repo/contents/${c.path}", body.toString()), "push ${c.path}")
            val commit = JSONObject(answer).optJSONObject("commit")?.optString("sha")?.take(7) ?: "?"
            sb.append("коммит $commit · ${c.path}\n")
        }
        return sb.toString().trim()
    }

    private fun contentsDelete(repo: String, path: String, message: String): String {
        val existing = call("GET", "/repos/$repo/contents/$path")
        if (existing.status == 404) return "нет такого файла: $path"
        val sha = JSONObject(existing.text).optString("sha")
        ok(
            call("DELETE", "/repos/$repo/contents/$path", JSONObject().put("message", message).put("sha", sha).toString()),
            "удаление $path",
        )
        return "удалён $path"
    }

    fun fileGet(repo: String, path: String, ref: String?): String {
        val q = if (ref.isNullOrBlank()) "" else "?ref=$ref"
        val t = get("/repos/$repo/contents/$path$q", "file_get", raw = true)
        return t.take(MAX_OUTPUT) + if (t.length > MAX_OUTPUT) "\n… (обрезано)" else ""
    }

    fun workflowCreate(repo: String, filename: String, yaml: String): String =
        pushFiles(repo, listOf(".github/workflows/$filename" to yaml), "workflow: $filename", null)

    /** Triggers workflow_dispatch. `workflow` is the file name, e.g. run.yml. */
    fun dispatch(repo: String, workflow: String, ref: String?): String {
        val branch = ref ?: branchName(repo, null)
        val body = JSONObject().put("ref", branch)
        ok(call("POST", "/repos/$repo/actions/workflows/$workflow/dispatches", body.toString()), "dispatch")
        return "workflow $workflow запущен (branch $branch). Дождаться результата: github run_wait {\"repo\":\"$repo\",\"timeout_sec\":600}"
    }

    fun runs(repo: String, limit: Int): String {
        val arr = JSONObject(get("/repos/$repo/actions/runs?per_page=${limit.coerceIn(1, 30)}", "runs"))
            .optJSONArray("workflow_runs") ?: JSONArray()
        val sb = StringBuilder()
        for (i in 0 until arr.length()) {
            sb.append(runLine(arr.getJSONObject(i))).append('\n')
        }
        return sb.toString().ifEmpty { "(запусков нет)" }
    }

    private fun runLine(r: JSONObject): String {
        val conclusion = r.optString("conclusion").takeIf { it.isNotEmpty() && it != "null" } ?: "…"
        return "run #${r.optLong("run_number")} id=${r.optLong("id")} ${r.optString("status")}/$conclusion " +
            "${r.optString("name")} (${r.optString("event")}, ${r.optString("created_at")})"
    }

    /**
     * Blocks until the run finishes — one tool call instead of a polling loop
     * that burns a round every few seconds. Reports the conclusion, the jobs
     * and, when something failed, the tail of the log, which is exactly what
     * "сборка упала, почему?" needs.
     */
    fun runWait(
        repo: String,
        runId: Long?,
        timeoutSec: Int,
        isCancelled: () -> Boolean = { false },
        logLines: Int = 40,
    ): String {
        val id = runId ?: latestRunId(repo)
        val budget = timeoutSec.coerceIn(15, MAX_WAIT_SEC) * 1000L
        val deadline = System.currentTimeMillis() + budget
        var run: JSONObject
        var waited = 0
        while (true) {
            run = JSONObject(get("/repos/$repo/actions/runs/$id", "запуск $id"))
            if (run.optString("status") == "completed") break
            val left = deadline - System.currentTimeMillis()
            if (left <= 0) {
                return "запуск ${run.optLong("run_number")} (id=$id) всё ещё ${run.optString("status")} " +
                    "через ${timeoutSec}с — он продолжается на раннере; вызови github run_wait ещё раз " +
                    "или отмени его: github run_cancel {\"repo\":\"$repo\",\"run_id\":$id}"
            }
            if (isCancelled()) return "ожидание отменено пользователем (запуск $id продолжается на раннере)"
            val napMs = minOf(WAIT_POLL_MS, left)
            waited += napMs.toInt()
            Thread.sleep(napMs)
        }
        val sb = StringBuilder()
        val conclusion = run.optString("conclusion")
        val shown = run.optString("conclusion").takeIf { it.isNotEmpty() && it != "null" } ?: "…"
        sb.append("запуск #${run.optLong("run_number")} id=$id: ${run.optString("status")}/$shown «${run.optString("name")}»\n")
        sb.append("длительность: ${durationSec(run)}с, ожидание: ${waited / 1000}с\n")
        sb.append("ссылка: ${run.optString("html_url")}\n")
        jobsSummary(repo, id)?.let { sb.append(it) }
        if (!conclusion.equals("success", ignoreCase = true)) {
            sb.append("— логи (хвост) —\n")
            sb.append(logTail(repo, id, logLines))
        }
        return sb.toString()
    }

    private fun latestRunId(repo: String): Long {
        val arr = JSONObject(get("/repos/$repo/actions/runs?per_page=1", "runs"))
            .optJSONArray("workflow_runs") ?: JSONArray()
        if (arr.length() == 0) throw GitHubException("в $repo ещё не было запусков — сначала github dispatch")
        return arr.getJSONObject(0).optLong("id")
    }

    private fun durationSec(run: JSONObject): Long {
        val created = run.optString("created_at")
        val updated = run.optString("updated_at")
        return if (created.isEmpty() || updated.isEmpty()) 0 else seconds(created, updated)
    }

    /** ISO-8601 like 2026-09-27T10:00:00Z — parsed without java.time (API 26). */
    private fun seconds(from: String, to: String): Long = try {
        val format = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", Locale.US)
        format.timeZone = java.util.TimeZone.getTimeZone("UTC")
        format.parse(to).time / 1000 - format.parse(from).time / 1000
    } catch (t: Throwable) {
        0
    }

    private fun jobsSummary(repo: String, runId: Long): String? {
        val arr = JSONObject(get("/repos/$repo/actions/runs/$runId/jobs", "jobs"))
            .optJSONArray("jobs") ?: return null
        if (arr.length() == 0) return null
        val sb = StringBuilder("задачи:\n")
        for (i in 0 until arr.length()) {
            val job = arr.getJSONObject(i)
            val conclusion = job.optString("conclusion").takeIf { it.isNotEmpty() && it != "null" } ?: job.optString("status")
            sb.append("  ${job.optString("name")}: $conclusion")
            val steps = job.optJSONArray("steps")
            if (steps != null && !conclusion.equals("success", ignoreCase = true)) {
                val failed = mutableListOf<String>()
                for (s in 0 until steps.length()) {
                    val step = steps.getJSONObject(s)
                    val sc = step.optString("conclusion")
                    if (sc.isNotEmpty() && sc != "success" && sc != "skipped") failed += step.optString("name")
                }
                if (failed.isNotEmpty()) sb.append(" (упали шаги: ${failed.joinToString(", ")})")
            }
            sb.append('\n')
        }
        return sb.toString()
    }

    private fun logTail(repo: String, runId: Long, lines: Int): String = try {
        val text = stream("GET", "/repos/$repo/actions/runs/$runId/logs").use { ins -> zipToText(ins, MAX_ZIP_TEXT) }
        val all = text.lines().filter { it.isNotBlank() }
        if (all.size <= lines) all.joinToString("\n").ifEmpty { "(логи пусты)" }
        else all.takeLast(lines).joinToString("\n").let { "…\n$it" }
    } catch (t: Throwable) {
        "не удалось прочитать логи: ${t.message ?: t.javaClass.simpleName}"
    }

    fun runCancel(repo: String, runId: Long): String {
        ok(call("POST", "/repos/$repo/actions/runs/$runId/cancel", "{}"), "отмена запуска")
        return "запуск $runId отменён"
    }

    /** Run logs come as a zip of per-job text files. */
    fun logs(repo: String, runId: Long): String {
        stream("GET", "/repos/$repo/actions/runs/$runId/logs").use { ins ->
            return zipToText(ins, MAX_ZIP_TEXT).ifEmpty { "(логи пусты)" }
        }
    }

    fun artifacts(repo: String, runId: Long?): String {
        val q = if (runId != null) "?run_id=$runId" else ""
        val arr = JSONObject(get("/repos/$repo/actions/artifacts$q", "artifacts"))
            .optJSONArray("artifacts") ?: JSONArray()
        val sb = StringBuilder()
        for (i in 0 until arr.length()) {
            val a = arr.getJSONObject(i)
            sb.append("id=${a.optLong("id")} ${a.optString("name")} ${a.optLong("size_in_bytes")} bytes (run ${a.optLong("run_id")})\n")
        }
        return sb.toString().ifEmpty { "(артефактов нет)" }
    }

    /** Lists an artifact's files and inlines the small text ones. */
    fun artifactDownload(repo: String, artifactId: Long): String {
        stream("GET", "/repos/$repo/actions/artifacts/$artifactId/zip").use { ins ->
            return zipToText(ins, MAX_ZIP_TEXT).ifEmpty { "(пусто)" }
        }
    }

    /** Escape hatch: any GitHub REST call, e.g. PRs, issues, releases. */
    fun api(method: String, path: String, body: String?): String {
        val m = method.uppercase()
        if (m !in setOf("GET", "POST", "PATCH", "PUT", "DELETE")) throw GitHubException("метод $m не поддерживается")
        if (!path.startsWith("/")) throw GitHubException("path должен начинаться с /, например /repos/owner/name")
        val answer = call(m, path, body?.takeIf { it.isNotBlank() })
        val text = ok(answer, "api $m $path")
        return if (text.isBlank()) "(пустой ответ ${answer.status})" else pretty(text)
    }

    // ---------------------------------------------------------------- zip

    /** Reads a zip stream: lists entries and inlines the small text ones. */
    private fun zipToText(ins: InputStream, cap: Int): String {
        val sb = StringBuilder()
        java.util.zip.ZipInputStream(ins).use { zip ->
            var entry = zip.nextEntry
            val buf = ByteArray(8192)
            while (entry != null && sb.length < cap) {
                if (!entry.isDirectory) {
                    sb.append("── ").append(entry.name).append('\n')
                    if (looksTexty(entry.name)) {
                        val text = StringBuilder()
                        while (true) {
                            val n = zip.read(buf)
                            if (n <= 0 || text.length >= cap - sb.length) break
                            text.append(String(buf, 0, n, Charsets.UTF_8))
                        }
                        sb.append(text).append('\n')
                    }
                }
                entry = zip.nextEntry
            }
        }
        return sb.toString().take(cap)
    }

    private fun looksTexty(name: String): Boolean {
        if (name.endsWith(".png") || name.endsWith(".jpg") || name.endsWith(".jar") || name.endsWith(".apk") ||
            name.endsWith(".zip") || name.endsWith(".dex") || name.endsWith(".so") || name.endsWith(".bin")
        ) return false
        return true
    }

    private fun plural(n: Int, one: String, few: String, many: String): String = when {
        n % 10 == 1 && n % 100 != 11 -> one
        n % 10 in 2..4 && n % 100 !in 12..14 -> few
        else -> many
    }
}

